parameters.jsCode:
// Triage severity and complexity
// Rules on estimated amount, injury involvement, liability questions, multiple parties and coverage ambiguity produce a severity tier and a complexity flag.
return $input.all();

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "summary": { "type": "string" },
    "draft": { "type": "string", "description": "The message or document text this step produced, ready to send or review" },
    "subject": { "type": "string" },
    "confidence": { "type": "number" },
    "needs_human": { "type": "boolean" },
    "reasons": { "type": "array", "items": { "type": "string" } }
  },
  "required": ["summary", "confidence", "needs_human"]
}
